// Cheap checks first: every rejected request here costs nothing downstream.
// Accepts a recording (form field "audio") or a typed turn (form field "message").
const MAX_BYTES = 5 * 1024 * 1024;   // ~5 minutes of speech
const MIN_BYTES = 1000;              // shorter than this is silence or a broken recording
const ALLOWED = ['audio/webm', 'video/webm', 'audio/mp4', 'audio/x-m4a', 'audio/m4a', 'audio/aac', 'audio/ogg', 'audio/mpeg', 'audio/wav', 'audio/x-wav'];

const item = $input.first();
const headers = item.json.headers || {};
const body = item.json.body || {};
const requestId = String(headers['x-request-id'] || $execution.id).slice(0, 80);
// One session = one conversation. The page sends the same id for every turn of a call.
const sessionId = String(headers['x-session-id'] || body.sessionId || '').replace(/[^\w.-]/g, '').slice(0, 80) || `req-${requestId}`;
// Fault injection for tests. Only sessions named test-* can use it, so callers can't trigger it.
const simulate = sessionId.startsWith('test-') ? String(headers['x-simulate-failure'] || '').toLowerCase() : '';
const base = { requestId, sessionId, simulate, startedAt: Date.now() };
const reject = (error, extra = {}) => [{ json: { ...base, ok: false, status: 400, error, ...extra } }];

const bin = item.binary && item.binary.audio;
const typed = String(body.message || '').trim().slice(0, 1000);
if (!bin && typed) return [{ json: { ...base, ok: true, needsStt: false, callerText: typed, bytes: 0, mimeType: 'text/plain' } }];
if (!bin) return reject('No recording received. Send it as a form field named "audio", or type a "message".');

const mimeType = (bin.mimeType || '').split(';')[0].trim().toLowerCase();
const bytes = (await this.helpers.getBinaryDataBuffer(0, 'audio')).length;

if (bytes < MIN_BYTES) return reject(`The recording is empty or too short (${bytes} bytes). Speak for at least a second.`, { bytes, mimeType });
if (bytes > MAX_BYTES) return reject(`The recording is ${(bytes / 1048576).toFixed(1)} MB. The limit is 5 MB.`, { bytes, mimeType });
if (!ALLOWED.includes(mimeType)) return reject(`Audio type "${mimeType || 'unknown'}" isn't supported. Send webm, mp4/m4a, ogg, mp3 or wav.`, { bytes, mimeType });

return [{ json: { ...base, ok: true, needsStt: true, bytes, mimeType }, binary: item.binary }];

// Guardrail: runs BEFORE the AI agent. Anything that sounds like an emergency gets a fixed,
// reviewed safety script. The LLM never improvises on these.
const URGENT = [
  /chest pain/i, /heart attack/i, /stroke/i,
  /can'?t breathe|cannot breathe|trouble breathing|difficulty breathing|short(ness)? of breath|struggling to breathe/i,
  /unconscious|passed out|fainted|not responding/i,
  /heavy bleeding|bleeding (a lot|heavily|badly)|won'?t stop bleeding/i,
  /hit (my|his|her|their) head|head injury|fell .*head/i,
  /suicid|kill myself|overdose/i,
];
const callerText = String($input.first().json.callerText || '').trim();
const matched = URGENT.find(r => r.test(callerText));
return [{ json: { callerText, urgent: Boolean(matched), matched: matched ? String(matched) : '' } }];

// clinic_faq tool. The agent calls this for any question about the clinic.
// Only facts listed here may be told to callers. Anything else: staff call back.
return [
  'Opening hours: Monday to Friday 9 a.m. to 5 p.m., last appointment starts at 4 p.m. Saturday 9 a.m. to 1 p.m., last appointment starts at 12 noon. Closed on Sunday.',
  'Therapists: Amina, Daniel and Sara.',
  'Appointments last 45 minutes and start on the hour.',
  'Bookings can be made from tomorrow up to 30 days ahead, by phone or with this assistant.',
  'Please bring comfortable clothes you can move in, and any scans or referral letters.',
  'Please give at least 24 hours notice to cancel or move an appointment.',
  'Prices, insurance and anything not listed here: a member of staff will call the caller back.',
].join('\n');
